{"explanation":"The line of best fit uses least squares: it minimizes the sum of squared vertical distances between the points and the line. Drag any point to see the fitted equation update immediately. The R² value measures how much of the variation in the points’ heights the line explains; values closer to 1 indicate a tighter fit.","manimCode":"const axes = new Axes({ xRange: [-5, 5, 1], yRange: [-3, 3, 1], xLength: 10, yLength: 4.6, tips: false });
const title = new Text({ text: 'A line that follows your data', fontSize: 32, color: WHITE });
title.moveTo([0, 3.25, 0]);
const equation = new Text({ text: '', fontSize: 24, color: YELLOW });
equation.moveTo([-2.4, 2.7, 0]);
const score = new Text({ text: '', fontSize: 24, color: WHITE });
score.moveTo([3.1, 2.7, 0]);
const caption = new Text({ text: 'Least squares minimizes squared vertical distances', fontSize: 20, color: GRAY });
caption.moveTo([0, -2.85, 0]);
const hint = new Text({ text: 'Drag any blue point to reshape the fit', fontSize: 22, color: BLUE });
hint.moveTo([0, -3.3, 0]);
scene.add(title, equation, score, caption, hint);
await scene.play(new Create(axes));

let data = [[-4, -1.5], [-3, -1.7], [-2, -0.3], [-0.8, -0.7], [0.6, 0.6], [1.8, 0.3], [3, 1.8], [4, 1.4]];
let fitCurve = null;
const residuals = data.map(p => new DashedLine({ start: axes.c2p(p[0], p[1]), end: axes.c2p(p[0], p[1] + 0.01), color: GRAY }));
residuals.forEach(segment => segment.setOpacity(0.45));
const handles = data.map(p => new Dot({ point: axes.c2p(p[0], p[1]), radius: 0.13, color: BLUE }));
scene.add(...residuals, ...handles);
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

function update() {
  const count = data.length;
  const meanX = data.reduce((total, p) => total + p[0], 0) / count;
  const meanY = data.reduce((total, p) => total + p[1], 0) / count;
  let xx = 0;
  let xy = 0;
  let yy = 0;
  data.forEach(([x, y]) => {
    xx += (x - meanX) * (x - meanX);
    xy += (x - meanX) * (y - meanY);
    yy += (y - meanY) * (y - meanY);
  });
  handles.forEach((dot, i) => dot.moveTo(axes.c2p(...data[i])));
  if (fitCurve) {
    scene.remove(fitCurve);
    fitCurve = null;
  }
  if (xx < 0.000001) {
    equation.setText('No unique fit: all x values coincide');
    score.setText('R²: undefined');
    residuals.forEach(segment => segment.setOpacity(0));
    return;
  }
  const slope = xy / xx;
  const intercept = meanY - slope * meanX;
  const predict = x => slope * x + intercept;
  let left = -5;
  let right = 5;
  if (Math.abs(slope) > 0.000001) {
    const edgeA = (-3 - intercept) / slope;
    const edgeB = (3 - intercept) / slope;
    left = Math.max(left, Math.min(edgeA, edgeB));
    right = Math.min(right, Math.max(edgeA, edgeB));
  }
  // Rebuild only the graph, because its visible domain changes with the fit.
  // Clipping the domain avoids drawing outside the plotting area.
  if (right > left) {
    fitCurve = axes.plot(predict, { xRange: [left, right, 0.05], color: YELLOW });
    fitCurve.setStrokeWidth(3);
    scene.add(fitCurve);
  }
  let squaredError = 0;
  data.forEach(([x, y], i) => {
    const fittedY = predict(x);
    squaredError += (y - fittedY) * (y - fittedY);
    residuals[i].setStart(axes.c2p(x, y));
    residuals[i].setEnd(axes.c2p(x, clamp(fittedY, -3, 3)));
    residuals[i].setOpacity(Math.abs(y - fittedY) < 0.001 ? 0 : 0.45);
  });
  const sign = intercept < 0 ? ' − ' : ' + ';
  equation.setText('y = ' + slope.toFixed(2) + 'x' + sign + Math.abs(intercept).toFixed(2));
  score.setText(yy < 0.000001 ? 'R²: undefined' : 'R² = ' + clamp(1 - squaredError / yy, 0, 1).toFixed(3));
  // Keep the handles in front of the line so they remain easy to grab.
  handles.forEach(dot => { scene.remove(dot); scene.add(dot); });
}

update();
handles.forEach((dot, i) => {
  makeDraggable(dot, scene, {
    onDrag: (mob, pos) => {
      const [x, y] = axes.pointToCoords(pos);
      data[i] = [clamp(x, -4.8, 4.8), clamp(y, -2.8, 2.8)];
      update();
    }
  });
});
await scene.wait(999999);"}

